from solution import fib4
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def ref_fib4(n: int) -> int:
    # Obviously-correct reference model, iterative.
    seq = [0, 0, 2, 0]
    if n < 4:
        return seq[n]
    for i in range(4, n + 1):
        seq.append(seq[-1] + seq[-2] + seq[-3] + seq[-4])
    return seq[n]


def test_base_case_0():
    assert fib4(0) == 0


def test_base_case_1():
    assert fib4(1) == 0


def test_base_case_2():
    assert fib4(2) == 2


def test_base_case_3():
    assert fib4(3) == 0


def test_first_recurrence_step_n4():
    # 0 + 0 + 2 + 0 = 2
    assert fib4(4) == 2


def test_docstring_example_5():
    assert fib4(5) == 4


def test_docstring_example_6():
    assert fib4(6) == 8


def test_docstring_example_7():
    assert fib4(7) == 14


def test_return_type_is_int():
    for n in [0, 1, 2, 3, 4, 5, 6, 7, 20]:
        assert type(fib4(n)) is int


@given(st.integers(min_value=0, max_value=50))
def test_matches_reference_model(n):
    assert fib4(n) == ref_fib4(n)


@given(st.integers(min_value=4, max_value=50))
def test_recurrence_relation(n):
    assert fib4(n) == fib4(n - 1) + fib4(n - 2) + fib4(n - 3) + fib4(n - 4)


@given(st.integers(min_value=0, max_value=100))
def test_nonnegative(n):
    assert fib4(n) >= 0


@given(st.integers(min_value=0, max_value=100))
def test_all_values_even(n):
    # All base cases even, sum of evens is even.
    assert fib4(n) % 2 == 0


@given(st.integers(min_value=3, max_value=100))
def test_nondecreasing_from_n3(n):
    # fib4(n+1) = fib4(n) + three non-negative terms >= fib4(n)
    assert fib4(n + 1) >= fib4(n)


@given(st.integers(min_value=5, max_value=100))
def test_strictly_increasing_from_n5(n):
    # Once past the initial zeros, growth is strict.
    assert fib4(n + 1) > fib4(n)


def test_efficiency_and_correctness_large_n():
    # "efficiently compute": must handle moderately large n quickly and correctly.
    assert fib4(100) == ref_fib4(100)
    assert fib4(500) == ref_fib4(500)
    assert fib4(1000) == ref_fib4(1000)


def test_determinism():
    assert fib4(7) == fib4(7)
    assert fib4(25) == ref_fib4(25)
